Bekræft lige én ting først, så jeg kan give dig **endelig** VS Code-konfiguration korrekt:

- Kører du **Windows native (MinGW/MSYS gcc + gdb)**  
eller  
- **WSL**?

Indtil du svarer, får du her de minimale, sikre kodeændringer (uafhængige af miljø).

## 1) Copy-paste ændringer til `client.c` (minimal, C, samme struktur)

```c
/* A simple client in the internet domain using TCP
The ip adresse and port number on server is passed as arguments
Based on example: https://www.linuxhowtos.org/C_C++/socket.htm

Modified: Michael Alrøe
*/

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <stdint.h>      // added for uint8_t
#include <sys/socket.h>
#include <netdb.h>
#include <netinet/in.h>  // for sockaddr_in

#define BUFSIZE 256

void error(const char *msg)
{
    perror(msg);
    exit(1);
}

int main(int argc, char *argv[])
{
    printf("Starting client...\n");

    int sockfd, portno, n;
    struct sockaddr_in serv_addr;
    struct hostent *server;
    uint8_t buffer[BUFSIZE];

    if (argc < 3)
        error("ERROR usage: hostname port");

    portno = atoi(argv[2]);
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
        error("ERROR opening socket");

    server = gethostbyname(argv[1]);
    if (server == NULL)
        error("ERROR no such host");

    printf("Server at: %s, port: %s\n", argv[1], argv[2]);

    printf("Connect...\n");
    bzero((char *)&serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    bcopy((char *)server->h_addr_list[0], (char *)&serv_addr.sin_addr.s_addr, server->h_length);
    serv_addr.sin_port = htons(portno);
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
        error("ERROR connecting");

    printf("Please enter the message: ");
    bzero(buffer, sizeof(buffer));
    if (fgets((char *)buffer, sizeof(buffer), stdin) == NULL)
        error("ERROR reading stdin");

    n = write(sockfd, buffer, strlen((char *)buffer));
    if (n < 0)
        error("ERROR writing to socket");

    bzero(buffer, sizeof(buffer));

    // Minimal robust receive: read up to BUFSIZE-1 and NUL-terminate
    n = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (n < 0)
        error("ERROR reading from socket");
    if (n == 0)
        printf("Server closed connection without reply.\n");
    else {
        buffer[n] = '\0';
        printf("\n%s\n", (char *)buffer);
    }

    printf("Closing client...\n\n");
    close(sockfd);
    return 0;
}
```

## 2) Copy-paste ændringer til `server.c` (minimal, C, samme struktur)

```c
/* A simple server in the internet domain using TCP
The port number is passed as an argument
Based on example: https://www.linuxhowtos.org/C_C++/socket.htm

Modified: Michael Alrøe
*/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>      // added for uint8_t
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define BUFSIZE_RX 200
#define BUFSIZE_TX 256

void error(const char *msg)
{
    perror(msg);
    exit(1);
}

int main(int argc, char *argv[])
{
    printf("Starting server...\n");

    int sockfd, newsockfd, portno;
    int n;
    int opt = 1; // for SO_REUSEADDR

    socklen_t clilen;
    uint8_t bufferRx[BUFSIZE_RX];
    uint8_t bufferTx[BUFSIZE_TX];
    struct sockaddr_in serv_addr, cli_addr;

    if (argc < 2)
        error("ERROR usage: port");

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
        error("ERROR opening socket");

    // Allow fast restart after close (very useful in demos)
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0)
        error("ERROR on setsockopt(SO_REUSEADDR)");

    printf("Binding...\n");
    bzero((char *)&serv_addr, sizeof(serv_addr));
    portno = atoi(argv[1]);
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
        error("ERROR on binding");

    printf("Listen...\n");
    listen(sockfd, 5);

    clilen = sizeof(cli_addr);

    for (;;)
    {
        printf("Accept...\n");
        newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (newsockfd < 0)
            error("ERROR on accept");

        printf("Accepted\n");

        bzero(bufferRx, sizeof(bufferRx));
        n = recv(newsockfd, bufferRx, sizeof(bufferRx) - 1, 0);
        if (n < 0) {
            close(newsockfd);
            error("ERROR reading from socket");
        }
        if (n == 0) {
            printf("Client closed connection without sending data.\n");
            close(newsockfd);
            continue;
        }

        bufferRx[n] = '\0';
        printf("Message: %s\n", (char *)bufferRx);

        snprintf((char *)bufferTx, sizeof(bufferTx), "Got message: %s", (char *)bufferRx);

        n = write(newsockfd, bufferTx, strlen((char *)bufferTx));
        if (n < 0) {
            close(newsockfd);
            error("ERROR writing to socket");
        }

        close(newsockfd);
    }

    close(sockfd);
    return 0;
}
```

---

## 3) VS Code config – to små options

## Option A: Windows native (MinGW/MSYS)

Brug `gcc` + `gdb` fra PATH (ingen `/usr/bin/...`).

### `tasks.json` (samme idé i både `client/.vscode` og `server/.vscode`)
```json
{
  "version": "2.0.0",
  "tasks": [
    {
      "label": "build-c",
      "type": "shell",
      "command": "gcc",
      "args": [
        "-Wall",
        "-Wextra",
        "-std=c11",
        "-g",
        "${workspaceFolder}/${fileBasename}",
        "-o",
        "${workspaceFolder}/${fileBasenameNoExtension}.exe"
      ],
      "problemMatcher": ["$gcc"],
      "group": { "kind": "build", "isDefault": true }
    }
  ]
}
```

### `launch.json` (client)
```json
{
  "version": "0.2.0",
  "configurations": [
    {
      "name": "Debug TCP Client (Windows)",
      "type": "cppdbg",
      "request": "launch",
      "program": "${workspaceFolder}/client.exe",
      "args": ["127.0.0.1", "9000"],
      "cwd": "${workspaceFolder}",
      "externalConsole": true,
      "MIMode": "gdb",
      "miDebuggerPath": "gdb",
      "preLaunchTask": "build-c"
    }
  ]
}
```

### `launch.json` (server)
```json
{
  "version": "0.2.0",
  "configurations": [
    {
      "name": "Debug TCP Server (Windows)",
      "type": "cppdbg",
      "request": "launch",
      "program": "${workspaceFolder}/server.exe",
      "args": ["9000"],
      "cwd": "${workspaceFolder}",
      "externalConsole": true,
      "MIMode": "gdb",
      "miDebuggerPath": "gdb",
      "preLaunchTask": "build-c"
    }
  ]
}
```

